// Authentication
function normalizeUsername(v){
  return v.trim().replace(/^@+/,"").toLowerCase();
}
function validUsername(v){ return /^[a-zA-Z0-9_]{3,32}$/.test(normalizeUsername(v)); }
function validPhone(v){ return /^\+?[0-9\s().-]{7,20}$/.test(v.trim()); }
function syntheticEmail(username){ return normalizeUsername(username)+"@telecod.local"; }

function openAuth(mode="login"){
  authMode=mode;
  $("#authModal").classList.add("open");
  $("#authModal").setAttribute("aria-hidden","false");
  setAuthMode(mode);
}
function closeAuth(){
  $("#authModal").classList.remove("open");
  $("#authModal").setAttribute("aria-hidden","true");
}
function setAuthMode(mode){
  authMode=mode;
  $("#tabLogin").classList.toggle("selected",mode==="login");
  $("#tabRegister").classList.toggle("selected",mode==="register");
  $("#loginPanel").classList.toggle("hidden",mode!=="login");
  $("#registerPanel").classList.toggle("hidden",mode!=="register");
}
function openRecovery(){
  closeAuth();
  $("#forgotModal").classList.add("open");
}
function closeRecovery(){ $("#forgotModal").classList.remove("open"); }

["#loginTop","#loginCta"].forEach(s=>$(s).onclick=()=>openAuth("login"));
["#registerTop","#registerCta"].forEach(s=>$(s).onclick=()=>openAuth("register"));
$("#tabLogin").onclick=()=>setAuthMode("login");
$("#tabRegister").onclick=()=>setAuthMode("register");
