$("#closeForgot").onclick=closeRecovery;
$("#backToLogin").onclick=()=>{closeRecovery();openAuth("login")};
$("#authModal").onclick=e=>{if(e.target.id==="authModal")closeAuth()};
$("#forgotModal").onclick=e=>{if(e.target.id==="forgotModal")closeRecovery()};

