function requireTerms(checked){
  if(!checked){toast(T[lang].termsRequired,"warning");return false}
  return true;
}

async function ensureSupabase(){
  if(!sup){toast(T[lang].authConfig,"error");return false}
  return true;
}

$("#loginForm").onsubmit=async e=>{
  e.preventDefault();
  const username=normalizeUsername($("#loginUsername").value);
  const password=$("#loginPassword").value;
  if(!validUsername(username)){toast(T[lang].invalidUsername,"error");return}
  if(password.length<6){toast(T[lang].passwordShort,"error");return}
  if(!requireTerms($("#loginTerms").checked))return;
  if(!(await ensureSupabase()))return;

  try{
    const {data,error}=await sup.auth.signInWithPassword({
      email:syntheticEmail(username),password
    });
    if(error)throw error;

    const prof=await sup.from("profiles").select("is_banned").eq("id",data.user.id).maybeSingle();
    if(prof.data?.is_banned){await sup.auth.signOut();throw new Error(lang==="id"?"Akun kamu diblokir admin.":"Your account has been blocked by an administrator.")}

    await sup.from("profiles").update({
      last_login_at:new Date().toISOString(),
      terms_accepted_at:new Date().toISOString()
    }).eq("id",data.user.id);

    closeAuth();
    toast(T[lang].loginSuccess,"success");
  }catch(err){
    console.error(err);
    toast(err.message||T[lang].authError,"error");
  }
};

$("#registerForm").onsubmit=async e=>{
  e.preventDefault();
  const username=normalizeUsername($("#registerUsername").value);
  const phone=$("#registerPhone").value.trim();
  const password=$("#registerPassword").value;
  const confirm=$("#registerConfirm").value;

  if(!validUsername(username)){toast(T[lang].invalidUsername,"error");return}
  if(!validPhone(phone)){toast(T[lang].invalidPhone,"error");return}
  if(password.length<6){toast(T[lang].passwordShort,"error");return}
  if(password!==confirm){toast(T[lang].passwordMismatch,"error");return}
  if(!requireTerms($("#registerTerms").checked))return;
  if(!(await ensureSupabase()))return;

  try{
    const fn=window.TELECOD_USERNAME_AUTH_FUNCTION_URL;
    if(fn && !fn.includes("YOUR-")){
      const r=await fetch(fn,{
        method:"POST",
        headers:{"Content-Type":"application/json"},
        body:JSON.stringify({
          action:"register",
          username,
          telegram_number:phone,
          password,
          terms_accepted:true
        })
      });
      const out=await r.json();
      if(!r.ok)throw new Error(out.error||T[lang].authError);
      if(out.email){
        const login=await sup.auth.signInWithPassword({email:out.email,password});
        if(login.error)throw login.error;
      }
    }else{
      const {data,error}=await sup.auth.signUp({
        email:syntheticEmail(username),
        password,
        options:{data:{username,telegram_username:username,telegram_number:phone,terms_accepted:true}}
      });
      if(error)throw error;
      if(data.user){
        await sup.from("profiles").upsert({
          id:data.user.id,username,telegram_username:username,telegram_number:phone,
          terms_accepted_at:new Date().toISOString()
        },{onConflict:"id"});
      }
    }

    closeAuth();
    toast(T[lang].registerSuccess,"success");
  }catch(err){
    console.error(err);
    toast(err.message||T[lang].authError,"error");
  }
};

// Telegram Login / Register via Telegram Login Widget + Supabase Edge Function.
// The bot token stays server-side in Supabase secrets.
function startTelegramAuth(mode="login"){
  const bot=window.TELECOD_TELEGRAM_BOT_USERNAME;
  const callback=window.TELECOD_TELEGRAM_AUTH_FUNCTION_URL;
  if(!bot || bot.includes("YOUR-") || !callback || callback.includes("YOUR-")){
    toast(T[lang].telegramConfig,"warning");
    return;
  }

  const authUrl=callback + (callback.includes("?")?"&":"?") + "mode=" + encodeURIComponent(mode);

  const modal=document.createElement("div");
  modal.className="telegram-widget-modal";
  modal.innerHTML=`
    <div class="telegram-widget-card">
      <button class="telegram-widget-close" type="button">×</button>
      <div class="auth-logo telegram-logo"><i class="fa-brands fa-telegram"></i></div>
      <h3>${mode==="recovery"?(lang==="id"?"Pulihkan dengan Telegram":"Recover with Telegram"):(lang==="id"?"Masuk dengan Telegram":"Continue with Telegram")}</h3>
      <p>${mode==="recovery"
        ?(lang==="id"?"Verifikasi akun melalui Telegram untuk membuat link reset kata sandi.":"Verify your account with Telegram to receive a password reset link.")
        :(lang==="id"?"Klik tombol Telegram di bawah untuk memverifikasi akun.":"Click the Telegram button below to verify your account.")}</p>
      <div id="telegramWidget"></div>
      <small>${lang==="id"?"Domain website harus sudah didaftarkan di BotFather.":"The website domain must be registered in BotFather."}</small>
    </div>`;
  document.body.appendChild(modal);
  modal.querySelector(".telegram-widget-close").onclick=()=>modal.remove();
  modal.onclick=e=>{if(e.target===modal)modal.remove()};

  const script=document.createElement("script");
  script.src="https://telegram.org/js/telegram-widget.js?22";
  script.async=true;
  script.dataset.telegramLogin=bot.replace(/^@/,"");
  script.dataset.size="large";
  script.dataset.userpic="false";
  script.dataset.authUrl=authUrl;
  script.dataset.requestAccess="write";
  modal.querySelector("#telegramWidget").appendChild(script);
}

$("#telegramLoginBtn").onclick=startTelegramAuth;
$("#telegramRegisterBtn").onclick=startTelegramAuth;
$("#telegramRecoveryBtn").onclick=()=>{closeRecovery();startTelegramAuth("recovery")};

sup?.auth.onAuthStateChange((event,session)=>{
  if(event==="SIGNED_IN" && session?.user) {
    document.body.classList.add("logged-in");
  }
  if(event==="SIGNED_OUT") document.body.classList.remove("logged-in");
});

async function stats(){
  if(!sup)return;
  try{
    const {data,error}=await sup.from("telecod_public_stats").select("*").maybeSingle();
    if(!error && data){
      $("#statUsers").textContent=Number(data.users||0).toLocaleString()+"+";
      $("#statPastes").textContent=Number(data.pastes||0).toLocaleString()+"+";
      $("#statViews").textContent=Number(data.transactions||0).toLocaleString()+"+";
      return;
    }
    const {count}=await sup.from("pastelinks").select("*",{count:"exact",head:true});
    if(count!=null) $("#statPastes").textContent=count.toLocaleString()+"+";
  }catch(e){console.warn(e)}
}
stats();
